import{c as a,Q as e,j as n,m as t}from"./chunks/framework.DVSyX6JR.js";const g=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"docs/cli.md","filePath":"docs/cli.md"}'),i={name:"docs/cli.md"};function o(p,s,l,r,d,h){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>The CLI reference covers all commands available on MeshCoreNG repeaters, room servers and sensors.</p><p>The full command reference is maintained in the repository:</p><ul><li><a href="https://github.com/MichTronics/MeshCoreNG/blob/main/docs/cli_commands.md" target="_blank" rel="noreferrer">CLI Commands — full reference</a></li></ul><h2 id="meshcoreng-specific-commands" tabindex="-1">MeshCoreNG-specific commands <a class="header-anchor" href="#meshcoreng-specific-commands" aria-label="Permalink to &quot;MeshCoreNG-specific commands&quot;">​</a></h2><p>These commands are added by MeshCoreNG on top of the standard MeshCore CLI.</p><h3 id="dense-mesh" tabindex="-1">Dense mesh <a class="header-anchor" href="#dense-mesh" aria-label="Permalink to &quot;Dense mesh&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get dense.stats            — show dense-mesh statistics</span></span>
<span class="line"><span>clear dense.stats          — reset statistics</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get flood.advert.base      — get flood advert forwarding base probability</span></span>
<span class="line"><span>set flood.advert.base &lt;v&gt;  — set (0=off, 0.308=default, 1=always forward)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get flood.relay.prob       — get relay probability (0-255)</span></span>
<span class="line"><span>set flood.relay.prob &lt;v&gt;   — set (0=never, 128=half, 255=always)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get flood.dynamic.enable   — get dynamic mode state</span></span>
<span class="line"><span>set flood.dynamic.enable on|off</span></span></code></pre></div><h3 id="internet-bridge-tcp" tabindex="-1">Internet bridge (TCP) <a class="header-anchor" href="#internet-bridge-tcp" aria-label="Permalink to &quot;Internet bridge (TCP)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set wifi.ssid &lt;name&gt;</span></span>
<span class="line"><span>set wifi.password &lt;pass&gt;</span></span>
<span class="line"><span>set bridge.server &lt;host&gt;</span></span>
<span class="line"><span>set bridge.port &lt;port&gt;</span></span>
<span class="line"><span>set bridge.password &lt;pass&gt;</span></span>
<span class="line"><span>set bridge.enabled on|off</span></span>
<span class="line"><span>set bridge.rf on|off       — allow bridge flood packets onto LoRa RF</span></span>
<span class="line"><span>get bridge.type            — shows &quot;tcp&quot;, &quot;rs232&quot; or &quot;espnow&quot;</span></span></code></pre></div><p>Python room server over the TCP bridge:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/python_room_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bridge-hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --bridge-password</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bridge-pas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Python Room&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span></span></code></pre></div><p>The room identity is stored in <code>python_room_server_state.json</code> by default. Keep that file, or pass a fixed <code>--state &lt;path&gt;</code>, so clients keep recognizing the same room after restarts.</p><h3 id="bridge-health" tabindex="-1">Bridge health <a class="header-anchor" href="#bridge-health" aria-label="Permalink to &quot;Bridge health&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get bridge.status          — show current bridge connection state when supported</span></span>
<span class="line"><span>get node.info              — show node info used by bridge/status pages when supported</span></span></code></pre></div><h3 id="power-saving" tabindex="-1">Power saving <a class="header-anchor" href="#power-saving" aria-label="Permalink to &quot;Power saving&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>powersaving                — show state</span></span>
<span class="line"><span>powersaving on|off</span></span>
<span class="line"><span>get power.stats</span></span>
<span class="line"><span>clear power.stats</span></span></code></pre></div><h3 id="daily-reboot" tabindex="-1">Daily reboot <a class="header-anchor" href="#daily-reboot" aria-label="Permalink to &quot;Daily reboot&quot;">​</a></h3><p>Repeater-only and TCP bridge repeater builds can optionally reboot on an uptime timer. The feature is disabled by default and is not included in RS232 or ESP-NOW bridge builds.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set reboot.daily on|off</span></span>
<span class="line"><span>set reboot.interval &lt;1-168&gt;</span></span>
<span class="line"><span>get reboot</span></span></code></pre></div><p>When the timer expires, the firmware waits for the outbound TX queue to become idle, then reboots the board. <code>set reboot.daily on</code> uses a 24-hour interval unless changed with <code>set reboot.interval</code>.</p><h3 id="atlas-observer" tabindex="-1">Atlas observer <a class="header-anchor" href="#atlas-observer" aria-label="Permalink to &quot;Atlas observer&quot;">​</a></h3><p>Atlas is disabled by default. It is a local telemetry/export foundation and does not change routing behavior.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>atlas enable on|off</span></span>
<span class="line"><span>atlas position on|off</span></span>
<span class="line"><span>atlas neighbors on|off</span></span>
<span class="line"><span>atlas pathsample on|off|0-10</span></span>
<span class="line"><span>atlas export on|off</span></span>
<span class="line"><span>get atlas.stats</span></span>
<span class="line"><span>observer export json</span></span></code></pre></div><h3 id="dutch-region-database" tabindex="-1">Dutch region database <a class="header-anchor" href="#dutch-region-database" aria-label="Permalink to &quot;Dutch region database&quot;">​</a></h3><p>The Dutch region database is a generated, read-only lookup table stored in firmware flash. It can be used by the CLI or a companion app to find Dutch location region codes without loading a database into RAM. It is controlled by the <code>WITH_DUTCH_REGION_DB</code> build flag.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>regiondb                  — show database metadata</span></span>
<span class="line"><span>regiondb info             — show entries, provinces, code count and source revision</span></span>
<span class="line"><span>regiondb provinces        — list province abbreviations and counts</span></span>
<span class="line"><span>regiondb find &lt;prefix&gt;    — find a location by name prefix</span></span>
<span class="line"><span>regiondb get &lt;index&gt;      — show all codes for a location</span></span>
<span class="line"><span>regiondb code &lt;code_id&gt;   — resolve an internal region-code ID</span></span></code></pre></div><p>The full generated-format documentation is maintained in the repository:</p><ul><li><a href="https://github.com/MichTronics/MeshCoreNG/blob/main/docs/dutch_region_db.md" target="_blank" rel="noreferrer">Dutch Region Database</a></li></ul><h3 id="runtime-regions" tabindex="-1">Runtime regions <a class="header-anchor" href="#runtime-regions" aria-label="Permalink to &quot;Runtime regions&quot;">​</a></h3><p>Runtime regions are editable forwarding scopes used by repeaters, room servers and tooling.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>region put &lt;name&gt; [parent]</span></span>
<span class="line"><span>region allowf &lt;name&gt;</span></span>
<span class="line"><span>region denyf &lt;name&gt;</span></span>
<span class="line"><span>region home &lt;name&gt;</span></span>
<span class="line"><span>region tree</span></span>
<span class="line"><span>region save</span></span></code></pre></div>`,32)])])}const b=a(i,[["render",o]]);export{g as __pageData,b as default};
